VALUES ('muse-greyleaders-cn', '灰条标题 + 方形照片', '顶部姓名区与分栏正文。支持肖像，未上传时显示剪影占位。内容较多时按 A4 自然分页。', @muse_sample_general, CAST('{"schema_version":"template-definition.v1","template_key":"muse-greyleaders-cn","semantic_labels":{"profile":"个人简介","work":"工作经历","education":"教育经历","project":"项目经历","skills":"专业技能","activity":"实践经历","interests":"兴趣爱好","certificates":"证书与语言","awards":"荣誉奖项","languages":"语言能力"},"regions":[{"region_id":"header","region_kind":"header","order":0},{"region_id":"main","region_kind":"main","order":1},{"region_id":"sidebar","region_kind":"sidebar","order":2}],"slots":[{"slot_id":"identity","region_id":"header","accepts":["identity"],"universal_fallback":false,"order":0},{"slot_id":"support","region_id":"sidebar","accepts":["skills","certificates","languages","interests","education"],"universal_fallback":false,"order":1},{"slot_id":"content","region_id":"main","accepts":["identity","profile","work","education","project","skills","activity","interests","certificates","awards","languages","custom"],"universal_fallback":true,"order":10}],"tokens":{"font_family":"system-ui","font_size_pt":10,"line_height":1.5,"accent_color":"#333333","page_margin_mm":12},"avatar":{"visibility":"show","fallback_asset":"system-default","size_px":94,"region_id":"header"}}' AS JSON), 1, LEAST(@muse_sort_start + 760, 1000000))
ON DUPLICATE KEY UPDATE
  is_active = IF(
    resume_templates.name = VALUES(name)
    AND resume_templates.description = VALUES(description)
    AND resume_templates.data_json = VALUES(data_json)
    AND resume_templates.style_json = VALUES(style_json),
    resume_templates.is_active,
    NULL
  );

